// pages/CouponCenter.jsx
import React, { useEffect, useState } from 'react';
import { fetchMyCoupons, redeemCoupon } from '../api/couponApi';

function CouponCenter() {
  const [coupons, setCoupons] = useState([]);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchMyCoupons();
        setCoupons(res.data || []);
      } catch (err) {
        console.error('load coupons', err);
      }
    };
    load();
  }, []);

  const handleCopy = (code) => {
    navigator.clipboard.writeText(code);
    alert('쿠폰 코드가 복사되었습니다.');
  };

  const handleRedeem = async (id) => {
    try {
      const res = await redeemCoupon(id);
      alert('쿠폰 사용 완료!');
      setCoupons(coupons.map(c => (c._id === id ? res.data.coupon : c)));
    } catch (err) {
      alert('사용 실패: ' + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>내 쿠폰</h2>

      {coupons.length === 0 && <p>아직 쿠폰이 없습니다.</p>}

      {coupons.map(coupon => (
        <div key={coupon._id} style={{ padding: 12, border: '1px solid #ddd', marginBottom: 8, borderRadius: 8 }}>
          <div><strong>{coupon.brand}</strong> — {coupon.discount}% 할인</div>
          <div style={{ marginTop: 6 }}>코드: <strong>{coupon.code}</strong></div>

          {coupon.externalUrl && (
            <button
              style={{ marginTop: 6 }}
              onClick={() => window.open(coupon.externalUrl)}
            >
              사용처 이동
            </button>
          )}

          <button style={{ marginLeft: 8 }} onClick={() => handleCopy(coupon.code)}>
            코드 복사
          </button>

          {!coupon.redeemed && (
            <button style={{ marginLeft: 8 }} onClick={() => handleRedeem(coupon._id)}>
              쿠폰 사용
            </button>
          )}

          {coupon.redeemed && <span style={{ marginLeft: 8, color: 'green' }}>✓ 사용됨</span>}
        </div>
      ))}
    </div>
  );
}

export default CouponCenter;
